COPY public.rules_audit_log (id, table_name, record_id, action, old_value, new_value, changed_by, changed_at, reason) FROM stdin;
1	formulas	PETROLEUM_SAD_P1P2_2026	CREATE	\N	{"version": 1, "end_date": null, "is_active": true, "variables": [{"name": "DV", "type": "number", "unit": "USD/ton", "description": "Deduction Value per metric ton"}, {"name": "ex_rate", "type": "number", "unit": "KHR/USD", "description": "Exchange rate (exact, never rounded)"}, {"name": "net_mass_kg", "type": "number", "unit": "kg", "description": "Net mass in kilograms (exact)"}, {"name": "volume_ltr", "type": "number", "unit": "liter", "description": "Volume in liters (exact)"}, {"name": "CIF_USD", "type": "number", "unit": "USD", "description": "Customs value in USD for Phase 2"}, {"name": "cd_rate", "type": "number", "unit": "fraction", "description": "Customs duty rate (e.g. 0 for petroleum)"}, {"name": "atp_rate", "type": "number", "unit": "USD/L", "description": "ATP rate per liter (e.g. 0.02)"}, {"name": "st_rate", "type": "number", "unit": "fraction", "description": "Special tax rate (e.g. 0.30)"}, {"name": "vat_rate", "type": "number", "unit": "fraction", "description": "VAT rate (e.g. 0.10)"}], "expression": "{\\"phase_1\\": {\\"description\\": \\"ON SAD \\\\u2014 Deduction Value basis (importer pays this)\\", \\"steps\\": [{\\"step\\": 1, \\"name\\": \\"CPP_base\\", \\"formula\\": \\"ROUND((DV * ex_rate * net_mass_kg) / 1000)\\"}, {\\"step\\": 2, \\"name\\": \\"CPP\\", \\"formula\\": \\"ROUND_UP_100(ROUND(CPP_base * cd_rate))\\"}, {\\"step\\": 3, \\"name\\": \\"ATP\\", \\"formula\\": \\"ROUND_UP_100(ROUND(volume_ltr * atp_rate * ex_rate))\\"}, {\\"step\\": 4, \\"name\\": \\"SPP_base\\", \\"formula\\": \\"CPP_base + CPP + ATP\\"}, {\\"step\\": 5, \\"name\\": \\"SPP\\", \\"formula\\": \\"ROUND_UP_100(ROUND(SPP_base * st_rate))\\"}, {\\"step\\": 6, \\"name\\": \\"VPP_base\\", \\"formula\\": \\"SPP_base + SPP\\"}, {\\"step\\": 7, \\"name\\": \\"VPP\\", \\"formula\\": \\"ROUND_UP_100(ROUND(VPP_base * vat_rate))\\"}, {\\"step\\": 8, \\"name\\": \\"TOTAL_P1\\", \\"formula\\": \\"CPP + ATP + SPP + VPP\\"}]}, \\"phase_2\\": {\\"description\\": \\"ACTUAL \\\\u2014 CIF basis (used only for DPP calculation)\\", \\"steps\\": [{\\"step\\": 1, \\"name\\": \\"CPP_base2\\", \\"formula\\": \\"ROUND(CIF_USD * ex_rate)\\"}, {\\"step\\": 2, \\"name\\": \\"CPP2\\", \\"formula\\": \\"ROUND_UP_100(ROUND(CPP_base2 * cd_rate))\\"}, {\\"step\\": 3, \\"name\\": \\"ATP2\\", \\"formula\\": \\"ATP\\"}, {\\"step\\": 4, \\"name\\": \\"SPP_base2\\", \\"formula\\": \\"CPP_base2 + CPP2 + ATP2\\"}, {\\"step\\": 5, \\"name\\": \\"SPP2\\", \\"formula\\": \\"ROUND_UP_100(ROUND(SPP_base2 * st_rate))\\"}, {\\"step\\": 6, \\"name\\": \\"VPP_base2\\", \\"formula\\": \\"SPP_base2 + SPP2\\"}, {\\"step\\": 7, \\"name\\": \\"VPP2\\", \\"formula\\": \\"ROUND_UP_100(ROUND(VPP_base2 * vat_rate))\\"}, {\\"step\\": 8, \\"name\\": \\"TOTAL_P2\\", \\"formula\\": \\"CPP2 + ATP2 + SPP2 + VPP2\\"}]}, \\"dpp\\": {\\"description\\": \\"Difference / Partial Subsidy (informational only)\\", \\"formula\\": \\"ABS(TOTAL_P1 - TOTAL_P2)\\", \\"labels\\": {\\"phase2_greater\\": \\"Additional charge (DPP) \\\\u2014 state collects more\\", \\"phase1_greater\\": \\"Subsidy by the state (DPP) \\\\u2014 state pays difference\\", \\"equal\\": \\"No difference between phases (DPP)\\"}, \\"note\\": \\"Importer ALWAYS pays TOTAL_P1. DPP is handled separately by the state.\\"}, \\"rounding_functions\\": {\\"ROUND\\": \\"Standard rounding to whole number (0.5 rounds up)\\", \\"ROUND_UP_100\\": \\"CEILING(amount / 100) * 100 \\\\u2014 always round UP to nearest 100\\"}, \\"critical_rules\\": [\\"Exchange rate is used EXACTLY as published \\\\u2014 never rounded\\", \\"Quantities (volume_ltr, net_mass_kg) are NEVER rounded\\", \\"Each tax component: calculate \\\\u2192 ROUND \\\\u2192 ROUND_UP_100\\", \\"Phase 1 bases feed into next component; Phase 2 is independent (CIF basis)\\"]}", "formula_id": "PETROLEUM_SAD_P1P2_2026", "description": "Cambodia GDCE petroleum import tax — two-phase SAD calculation. Phase 1 uses Deduction Value (DV) as the customs basis. Phase 2 uses actual CIF value. DPP is the absolute difference. Importer always pays Phase 1. Reference: PDF9072888682166520095-Copy.pdf (SAD spreadsheet).", "formula_name": "Petroleum SAD Phase 1 & Phase 2 with DPP", "formula_type": "petroleum", "effective_date": "2026-01-01"}	system	2026-08-10 18:40:07.008314	
